    // ---- B response arbiter, master io 128b: round-robin per beat, lock until taken ----
    logic [1:0] io_128b_b_rarb_req;
    assign io_128b_b_rarb_req = {((subtractive_axi_bid_bridge_id == 3) && subtractive_axi_bid_valid) && subtractive_axi_bvalid, ((mem1_axi_bid_bridge_id == 3) && mem1_axi_bid_valid) && mem1_axi_bvalid};
    logic [0:0] io_128b_b_rarb_lock, io_128b_b_rarb_rr;
    logic io_128b_b_rarb_locked;
    wire [0:0] io_128b_b_rarb_pick = (io_128b_b_rarb_rr == 1'd0) ? (io_128b_b_rarb_req[0] ? 1'd0 : 1'd1) : 
        io_128b_b_rarb_req[1] ? 1'd1 : 1'd0;
    wire [0:0] io_128b_b_rarb_gnt = io_128b_b_rarb_locked ? io_128b_b_rarb_lock : io_128b_b_rarb_pick;
    wire io_128b_b_rarb_gnt_valid = io_128b_b_rarb_locked || (|io_128b_b_rarb_req);
    wire io_128b_b_rgnt_mem1 = io_128b_b_rarb_gnt_valid && (io_128b_b_rarb_gnt == 1'd0);
    wire io_128b_b_rgnt_subtractive = io_128b_b_rarb_gnt_valid && (io_128b_b_rarb_gnt == 1'd1);
    wire io_128b_b_rarb_vld = (io_128b_b_rgnt_mem1 && io_128b_b_rarb_req[0]) || (io_128b_b_rgnt_subtractive && io_128b_b_rarb_req[1]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            io_128b_b_rarb_lock   <= '0;
            io_128b_b_rarb_rr     <= '0;
            io_128b_b_rarb_locked <= 1'b0;
        end else if (io_128b_b_rarb_vld && io_128b_bready) begin
            io_128b_b_rarb_locked <= 1'b0;
            io_128b_b_rarb_rr <= (io_128b_b_rarb_gnt == 1'd1) ? 1'd0 : io_128b_b_rarb_gnt + 1'b1;
        end else if (io_128b_b_rarb_vld) begin
            io_128b_b_rarb_lock   <= io_128b_b_rarb_gnt;       // offered, not taken: hold
            io_128b_b_rarb_locked <= 1'b1;
        end
    )

    // ---- R response arbiter, master io 128b: round-robin per beat, lock until taken ----
    logic [1:0] io_128b_r_rarb_req;
    assign io_128b_r_rarb_req = {((subtractive_axi_rid_bridge_id == 3) && subtractive_axi_rid_valid) && subtractive_axi_rvalid, ((mem1_axi_rid_bridge_id == 3) && mem1_axi_rid_valid) && mem1_axi_rvalid};
    logic [0:0] io_128b_r_rarb_lock, io_128b_r_rarb_rr;
    logic io_128b_r_rarb_locked;
    wire [0:0] io_128b_r_rarb_pick = (io_128b_r_rarb_rr == 1'd0) ? (io_128b_r_rarb_req[0] ? 1'd0 : 1'd1) : 
        io_128b_r_rarb_req[1] ? 1'd1 : 1'd0;
    wire [0:0] io_128b_r_rarb_gnt = io_128b_r_rarb_locked ? io_128b_r_rarb_lock : io_128b_r_rarb_pick;
    wire io_128b_r_rarb_gnt_valid = io_128b_r_rarb_locked || (|io_128b_r_rarb_req);
    wire io_128b_r_rgnt_mem1 = io_128b_r_rarb_gnt_valid && (io_128b_r_rarb_gnt == 1'd0);
    wire io_128b_r_rgnt_subtractive = io_128b_r_rarb_gnt_valid && (io_128b_r_rarb_gnt == 1'd1);
    wire io_128b_r_rarb_vld = (io_128b_r_rgnt_mem1 && io_128b_r_rarb_req[0]) || (io_128b_r_rgnt_subtractive && io_128b_r_rarb_req[1]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            io_128b_r_rarb_lock   <= '0;
            io_128b_r_rarb_rr     <= '0;
            io_128b_r_rarb_locked <= 1'b0;
        end else if (io_128b_r_rarb_vld && io_128b_rready) begin
            io_128b_r_rarb_locked <= 1'b0;
            io_128b_r_rarb_rr <= (io_128b_r_rarb_gnt == 1'd1) ? 1'd0 : io_128b_r_rarb_gnt + 1'b1;
        end else if (io_128b_r_rarb_vld) begin
            io_128b_r_rarb_lock   <= io_128b_r_rarb_gnt;       // offered, not taken: hold
            io_128b_r_rarb_locked <= 1'b1;
        end
    )

    // ================================================================
    // Slave 0: mem0 (64b)
    // ================================================================
    // Single master: cpu → mem0
    // Master width: 64b, Slave width: 64b
    // Using 64b path from adapter

    // AW channel (gated by address re-decode -- see _addr_decode_expr)
    wire cpu_64b_aw_to_mem0 = (cpu_64b_aw.addr <= 32'h0fffffff);
    wire cpu_64b_aw_gnt_mem0 = cpu_64b_aw_to_mem0 && !cpu_64b_aw_hold_mem0;
    assign mem0_axi_awid     = cpu_64b_aw_to_mem0 ? cpu_64b_aw.id : '0;
    assign mem0_axi_awaddr   = cpu_64b_aw_to_mem0 ? cpu_64b_aw.addr : '0;
    assign mem0_axi_awlen    = cpu_64b_aw_to_mem0 ? cpu_64b_aw.len : '0;
    assign mem0_axi_awsize   = cpu_64b_aw_to_mem0 ? cpu_64b_aw.size : '0;
    assign mem0_axi_awburst  = cpu_64b_aw_to_mem0 ? cpu_64b_aw.burst : '0;
    assign mem0_axi_awlock   = cpu_64b_aw_to_mem0 ? cpu_64b_aw.lock : '0;
    assign mem0_axi_awcache  = cpu_64b_aw_to_mem0 ? cpu_64b_aw.cache : '0;
    assign mem0_axi_awprot   = cpu_64b_aw_to_mem0 ? cpu_64b_aw.prot : '0;
    assign mem0_axi_awqos    = cpu_64b_aw_to_mem0 ? cpu_64b_aw.qos : '0;
    assign mem0_axi_awregion = cpu_64b_aw_to_mem0 ? cpu_64b_aw.region : '0;
    assign mem0_axi_awuser   = cpu_64b_aw_to_mem0 ? cpu_64b_aw.user : '0;
    assign mem0_axi_awnsaid  = cpu_64b_aw_to_mem0 ? cpu_64b_aw.nsaid : '0;  // AXI5 sideband
    assign mem0_axi_awtrace  = cpu_64b_aw_to_mem0 ? cpu_64b_aw.trace : '0;  // AXI5 sideband
    assign mem0_axi_awmpam  = cpu_64b_aw_to_mem0 ? cpu_64b_aw.mpam : '0;  // AXI5 sideband
    assign mem0_axi_awmecid  = cpu_64b_aw_to_mem0 ? cpu_64b_aw.mecid : '0;  // AXI5 sideband
    assign mem0_axi_awidunq  = cpu_64b_aw_to_mem0 ? cpu_64b_aw.idunq : '0;  // AXI5 sideband
    assign mem0_axi_awatop  = cpu_64b_aw_to_mem0 ? cpu_64b_aw.atop : '0;  // AXI5 sideband
    assign mem0_axi_awvalid  = cpu_64b_aw_gnt_mem0 && cpu_64b_awvalid;

    assign cpu_64b_w_sel_mem0 = cpu_64b_w_to_mem0;

    // W channel (gated by the W destination FIFO head)
    assign mem0_axi_wdata  = cpu_64b_w_to_mem0 ? cpu_64b_w.data : '0;
    assign mem0_axi_wstrb  = cpu_64b_w_to_mem0 ? cpu_64b_w.strb : '0;
    assign mem0_axi_wlast  = cpu_64b_w_to_mem0 ? cpu_64b_w.last : '0;
    assign mem0_axi_wuser  = cpu_64b_w_to_mem0 ? cpu_64b_w.user : '0;
    assign mem0_axi_wpoison = cpu_64b_w_to_mem0 ? cpu_64b_w.poison : '0;  // AXI5 sideband
    assign mem0_axi_wvalid = cpu_64b_w_to_mem0 && cpu_64b_wvalid;

    // Bready (master → slave) — gated on bid_valid so the path stays
    // open through the entire B handshake, not just the AW phase.
    assign mem0_axi_bready = cpu_64b_b_rgnt_mem0 ? cpu_64b_bready : '0;

    // Bridge ID (master → slave)
    assign mem0_axi_bridge_id_aw = cpu_64b_aw_to_mem0 ? cpu_bridge_id_aw : '0;

    // AR channel (gated by address re-decode -- see _addr_decode_expr)
    wire cpu_64b_ar_to_mem0 = (cpu_64b_ar.addr <= 32'h0fffffff);
    wire cpu_64b_ar_gnt_mem0 = cpu_64b_ar_to_mem0;
    assign mem0_axi_arid     = cpu_64b_ar_to_mem0 ? cpu_64b_ar.id : '0;
    assign mem0_axi_araddr   = cpu_64b_ar_to_mem0 ? cpu_64b_ar.addr : '0;
    assign mem0_axi_arlen    = cpu_64b_ar_to_mem0 ? cpu_64b_ar.len : '0;
    assign mem0_axi_arsize   = cpu_64b_ar_to_mem0 ? cpu_64b_ar.size : '0;
    assign mem0_axi_arburst  = cpu_64b_ar_to_mem0 ? cpu_64b_ar.burst : '0;
    assign mem0_axi_arlock   = cpu_64b_ar_to_mem0 ? cpu_64b_ar.lock : '0;
    assign mem0_axi_arcache  = cpu_64b_ar_to_mem0 ? cpu_64b_ar.cache : '0;
    assign mem0_axi_arprot   = cpu_64b_ar_to_mem0 ? cpu_64b_ar.prot : '0;
    assign mem0_axi_arqos    = cpu_64b_ar_to_mem0 ? cpu_64b_ar.qos : '0;
    assign mem0_axi_arregion = cpu_64b_ar_to_mem0 ? cpu_64b_ar.region : '0;
    assign mem0_axi_aruser   = cpu_64b_ar_to_mem0 ? cpu_64b_ar.user : '0;
    assign mem0_axi_arnsaid  = cpu_64b_ar_to_mem0 ? cpu_64b_ar.nsaid : '0;  // AXI5 sideband
    assign mem0_axi_artrace  = cpu_64b_ar_to_mem0 ? cpu_64b_ar.trace : '0;  // AXI5 sideband
    assign mem0_axi_armpam  = cpu_64b_ar_to_mem0 ? cpu_64b_ar.mpam : '0;  // AXI5 sideband
    assign mem0_axi_armecid  = cpu_64b_ar_to_mem0 ? cpu_64b_ar.mecid : '0;  // AXI5 sideband
    assign mem0_axi_aridunq  = cpu_64b_ar_to_mem0 ? cpu_64b_ar.idunq : '0;  // AXI5 sideband
    assign mem0_axi_arvalid  = cpu_64b_ar_to_mem0 && cpu_64b_arvalid;

    // Rready (master → slave) — gated on rid_valid so the path stays
    // open through the entire R handshake, not just the AR phase.
    assign mem0_axi_rready = cpu_64b_r_rgnt_mem0 ? cpu_64b_rready : '0;

    // Bridge ID (master → slave)
    assign mem0_axi_bridge_id_ar = cpu_64b_ar_to_mem0 ? cpu_bridge_id_ar : '0;


    // ================================================================
    // Slave 1: mem1 (128b)
    // ================================================================
    // Multi-master (3 masters) → mem1
    //   - dma (rw)
    //   - acc (rw)
    //   - io (rw)

    wire dma_128b_aw_to_mem1 = ((dma_128b_aw.addr >= 32'h10000000) && (dma_128b_aw.addr <= 32'h1fffffff));
    wire dma_128b_ar_to_mem1 = ((dma_128b_ar.addr >= 32'h10000000) && (dma_128b_ar.addr <= 32'h1fffffff));
    wire acc_128b_aw_to_mem1 = ((acc_128b_aw.addr >= 32'h10000000) && (acc_128b_aw.addr <= 32'h1fffffff));
    wire acc_128b_ar_to_mem1 = ((acc_128b_ar.addr >= 32'h10000000) && (acc_128b_ar.addr <= 32'h1fffffff));
    wire io_128b_aw_to_mem1 = ((io_128b_aw.addr >= 32'h10000000) && (io_128b_aw.addr <= 32'h1fffffff));
    wire io_128b_ar_to_mem1 = ((io_128b_ar.addr >= 32'h10000000) && (io_128b_ar.addr <= 32'h1fffffff));

    // AW request slots for mem1: arbitration at the slave pins
    assign dma_128b_aw_slot_mem1_in_valid = dma_128b_aw_to_mem1 && dma_128b_awvalid && !dma_128b_aw_hold_mem1;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_dma_128b_aw_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_128b_aw_slot_mem1_in_valid), .wr_ready(dma_128b_aw_slot_mem1_in_ready), .wr_data(dma_128b_aw),
        .rd_valid(dma_128b_aw_slot_mem1_valid), .rd_ready(dma_128b_aw_slot_mem1_ready), .rd_data(dma_128b_aw_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_128b_aw_slot_mem1_in_valid = acc_128b_aw_to_mem1 && acc_128b_awvalid && !acc_128b_aw_hold_mem1;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_acc_128b_aw_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_128b_aw_slot_mem1_in_valid), .wr_ready(acc_128b_aw_slot_mem1_in_ready), .wr_data(acc_128b_aw),
        .rd_valid(acc_128b_aw_slot_mem1_valid), .rd_ready(acc_128b_aw_slot_mem1_ready), .rd_data(acc_128b_aw_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_128b_aw_slot_mem1_in_valid = io_128b_aw_to_mem1 && io_128b_awvalid && !io_128b_aw_hold_mem1;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_io_128b_aw_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_128b_aw_slot_mem1_in_valid), .wr_ready(io_128b_aw_slot_mem1_in_ready), .wr_data(io_128b_aw),
        .rd_valid(io_128b_aw_slot_mem1_valid), .rd_ready(io_128b_aw_slot_mem1_ready), .rd_data(io_128b_aw_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for mem1: round-robin, lock until handshake ----
    logic [2:0] mem1_aw_arb_req;
    assign mem1_aw_arb_req = {io_128b_aw_slot_mem1_valid, acc_128b_aw_slot_mem1_valid, dma_128b_aw_slot_mem1_valid};
    logic [1:0] mem1_aw_arb_lock, mem1_aw_arb_rr;
    logic mem1_aw_arb_locked;
    wire [1:0] mem1_aw_arb_pick = (mem1_aw_arb_rr == 2'd0) ? (mem1_aw_arb_req[0] ? 2'd0 : mem1_aw_arb_req[1] ? 2'd1 : 2'd2) : 
        (mem1_aw_arb_rr == 2'd1) ? (mem1_aw_arb_req[1] ? 2'd1 : mem1_aw_arb_req[2] ? 2'd2 : 2'd0) : 
        mem1_aw_arb_req[2] ? 2'd2 : mem1_aw_arb_req[0] ? 2'd0 : 2'd1;
    wire mem1_aw_arb_gnt_valid = mem1_aw_arb_locked || (|mem1_aw_arb_req);
    wire [1:0] mem1_aw_arb_gnt = mem1_aw_arb_locked ? mem1_aw_arb_lock : mem1_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem1_aw_arb_lock   <= '0;
            mem1_aw_arb_rr     <= '0;
            mem1_aw_arb_locked <= 1'b0;
        end else begin
            if (mem1_axi_awvalid && mem1_axi_awready) begin
                mem1_aw_arb_locked <= 1'b0;
                mem1_aw_arb_rr <= (mem1_aw_arb_gnt == 2'd2) ? 2'd0 : mem1_aw_arb_gnt + 1'b1;
            end else if (mem1_axi_awvalid) begin
                mem1_aw_arb_lock   <= mem1_aw_arb_gnt;
                mem1_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire dma_128b_aw_gnt_mem1 = mem1_aw_arb_gnt_valid && (mem1_aw_arb_gnt == 2'd0) && mem1_aw_arb_req[0];
    wire acc_128b_aw_gnt_mem1 = mem1_aw_arb_gnt_valid && (mem1_aw_arb_gnt == 2'd1) && mem1_aw_arb_req[1];
    wire io_128b_aw_gnt_mem1 = mem1_aw_arb_gnt_valid && (mem1_aw_arb_gnt == 2'd2) && mem1_aw_arb_req[2];
    assign dma_128b_aw_slot_mem1_ready = dma_128b_aw_gnt_mem1 && mem1_axi_awready;
    assign acc_128b_aw_slot_mem1_ready = acc_128b_aw_gnt_mem1 && mem1_axi_awready;
    assign io_128b_aw_slot_mem1_ready = io_128b_aw_gnt_mem1 && mem1_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign mem1_axi_awid = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.id : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.id : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.id : '0);
    assign mem1_axi_awaddr = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.addr : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.addr : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.addr : '0);
    assign mem1_axi_awlen = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.len : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.len : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.len : '0);
    assign mem1_axi_awsize = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.size : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.size : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.size : '0);
    assign mem1_axi_awburst = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.burst : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.burst : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.burst : '0);
    assign mem1_axi_awlock = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.lock : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.lock : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.lock : '0);
    assign mem1_axi_awcache = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.cache : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.cache : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.cache : '0);
    assign mem1_axi_awprot = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.prot : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.prot : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.prot : '0);
    assign mem1_axi_awqos = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.qos : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.qos : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.qos : '0);
    assign mem1_axi_awregion = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.region : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.region : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.region : '0);
    assign mem1_axi_awuser = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.user : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.user : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.user : '0);
    assign mem1_axi_awnsaid = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.nsaid : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.nsaid : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.nsaid : '0);
    assign mem1_axi_awtrace = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.trace : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.trace : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.trace : '0);
    assign mem1_axi_awmpam = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.mpam : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.mpam : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.mpam : '0);
    assign mem1_axi_awmecid = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.mecid : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.mecid : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.mecid : '0);
    assign mem1_axi_awidunq = (dma_128b_aw_gnt_mem1 ? dma_128b_aw_slot_mem1.idunq : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_128b_aw_slot_mem1.idunq : '0) |
        (io_128b_aw_gnt_mem1 ? io_128b_aw_slot_mem1.idunq : '0);
    assign mem1_axi_awvalid = dma_128b_aw_gnt_mem1 || acc_128b_aw_gnt_mem1 || io_128b_aw_gnt_mem1;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [1:0] mem1_wowner_mem [16];
    logic [4:0] mem1_wowner_wptr, mem1_wowner_rptr;
    logic mem1_wowner_ahead;
    wire mem1_wowner_valid = (mem1_wowner_wptr != mem1_wowner_rptr);
    wire mem1_wowner_byp = !mem1_wowner_valid && !mem1_wowner_ahead && mem1_axi_awvalid;
    wire mem1_wowner_aw_hs = mem1_axi_awvalid && mem1_axi_awready;
    wire mem1_wowner_w_end = mem1_axi_wvalid && mem1_axi_wready && mem1_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem1_wowner_wptr  <= '0;
            mem1_wowner_rptr  <= '0;
            mem1_wowner_ahead <= 1'b0;
        end else begin
            if (mem1_wowner_aw_hs && mem1_wowner_ahead) begin
                mem1_wowner_ahead <= 1'b0;   // its W already went
            end else if (mem1_wowner_aw_hs && !(mem1_wowner_byp && mem1_wowner_w_end)) begin
                mem1_wowner_mem[mem1_wowner_wptr[3:0]] <= mem1_aw_arb_gnt;
                mem1_wowner_wptr <= mem1_wowner_wptr + 1'b1;
            end else if (!mem1_wowner_aw_hs && mem1_wowner_byp && mem1_wowner_w_end) begin
                mem1_wowner_ahead <= 1'b1;
            end
            if (mem1_wowner_valid && mem1_wowner_w_end) begin
                mem1_wowner_rptr <= mem1_wowner_rptr + 1'b1;
            end
        end
    )
    wire [1:0] mem1_wowner_head = mem1_wowner_valid ? mem1_wowner_mem[mem1_wowner_rptr[3:0]]
                                       : mem1_aw_arb_gnt;
    assign dma_128b_w_sel_mem1 = (mem1_wowner_valid || mem1_wowner_byp) && (mem1_wowner_head == 2'd0) && dma_128b_w_to_mem1;
    assign acc_128b_w_sel_mem1 = (mem1_wowner_valid || mem1_wowner_byp) && (mem1_wowner_head == 2'd1) && acc_128b_w_to_mem1;
    assign io_128b_w_sel_mem1 = (mem1_wowner_valid || mem1_wowner_byp) && (mem1_wowner_head == 2'd2) && io_128b_w_to_mem1;

    // W channel (owner-gated mux across writing masters)
    assign mem1_axi_wdata = ((dma_128b_w_sel_mem1 && dma_128b_wvalid) ? dma_128b_w.data : '0) |
        ((acc_128b_w_sel_mem1 && acc_128b_wvalid) ? acc_128b_w.data : '0) |
        ((io_128b_w_sel_mem1 && io_128b_wvalid) ? io_128b_w.data : '0);
    assign mem1_axi_wstrb = ((dma_128b_w_sel_mem1 && dma_128b_wvalid) ? dma_128b_w.strb : '0) |
        ((acc_128b_w_sel_mem1 && acc_128b_wvalid) ? acc_128b_w.strb : '0) |
        ((io_128b_w_sel_mem1 && io_128b_wvalid) ? io_128b_w.strb : '0);
    assign mem1_axi_wlast = ((dma_128b_w_sel_mem1 && dma_128b_wvalid) ? dma_128b_w.last : '0) |
        ((acc_128b_w_sel_mem1 && acc_128b_wvalid) ? acc_128b_w.last : '0) |
        ((io_128b_w_sel_mem1 && io_128b_wvalid) ? io_128b_w.last : '0);
    assign mem1_axi_wuser = ((dma_128b_w_sel_mem1 && dma_128b_wvalid) ? dma_128b_w.user : '0) |
        ((acc_128b_w_sel_mem1 && acc_128b_wvalid) ? acc_128b_w.user : '0) |
        ((io_128b_w_sel_mem1 && io_128b_wvalid) ? io_128b_w.user : '0);
    assign mem1_axi_wvalid = (dma_128b_w_sel_mem1 && dma_128b_wvalid) || (acc_128b_w_sel_mem1 && acc_128b_wvalid) || (io_128b_w_sel_mem1 && io_128b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign mem1_axi_bready = (dma_128b_b_rgnt_mem1 ? dma_128b_bready : '0) |
        (acc_128b_b_rgnt_mem1 ? acc_128b_bready : '0) |
        (io_128b_b_rgnt_mem1 ? io_128b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign mem1_axi_bridge_id_aw = (dma_128b_aw_gnt_mem1 ? dma_bridge_id_aw : '0) |
        (acc_128b_aw_gnt_mem1 ? acc_bridge_id_aw : '0) |
        (io_128b_aw_gnt_mem1 ? io_bridge_id_aw : '0);

    // AR request slots for mem1: arbitration at the slave pins
    assign dma_128b_ar_slot_mem1_in_valid = dma_128b_ar_to_mem1 && dma_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_dma_128b_ar_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_128b_ar_slot_mem1_in_valid), .wr_ready(dma_128b_ar_slot_mem1_in_ready), .wr_data(dma_128b_ar),
        .rd_valid(dma_128b_ar_slot_mem1_valid), .rd_ready(dma_128b_ar_slot_mem1_ready), .rd_data(dma_128b_ar_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_128b_ar_slot_mem1_in_valid = acc_128b_ar_to_mem1 && acc_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_acc_128b_ar_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_128b_ar_slot_mem1_in_valid), .wr_ready(acc_128b_ar_slot_mem1_in_ready), .wr_data(acc_128b_ar),
        .rd_valid(acc_128b_ar_slot_mem1_valid), .rd_ready(acc_128b_ar_slot_mem1_ready), .rd_data(acc_128b_ar_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_128b_ar_slot_mem1_in_valid = io_128b_ar_to_mem1 && io_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_io_128b_ar_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_128b_ar_slot_mem1_in_valid), .wr_ready(io_128b_ar_slot_mem1_in_ready), .wr_data(io_128b_ar),
        .rd_valid(io_128b_ar_slot_mem1_valid), .rd_ready(io_128b_ar_slot_mem1_ready), .rd_data(io_128b_ar_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for mem1: round-robin, lock until handshake ----
    logic [2:0] mem1_ar_arb_req;
    assign mem1_ar_arb_req = {io_128b_ar_slot_mem1_valid, acc_128b_ar_slot_mem1_valid, dma_128b_ar_slot_mem1_valid};
    logic [1:0] mem1_ar_arb_lock, mem1_ar_arb_rr;
    logic mem1_ar_arb_locked;
    wire [1:0] mem1_ar_arb_pick = (mem1_ar_arb_rr == 2'd0) ? (mem1_ar_arb_req[0] ? 2'd0 : mem1_ar_arb_req[1] ? 2'd1 : 2'd2) : 
        (mem1_ar_arb_rr == 2'd1) ? (mem1_ar_arb_req[1] ? 2'd1 : mem1_ar_arb_req[2] ? 2'd2 : 2'd0) : 
        mem1_ar_arb_req[2] ? 2'd2 : mem1_ar_arb_req[0] ? 2'd0 : 2'd1;
    wire mem1_ar_arb_gnt_valid = mem1_ar_arb_locked || (|mem1_ar_arb_req);
    wire [1:0] mem1_ar_arb_gnt = mem1_ar_arb_locked ? mem1_ar_arb_lock : mem1_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem1_ar_arb_lock   <= '0;
            mem1_ar_arb_rr     <= '0;
            mem1_ar_arb_locked <= 1'b0;
        end else begin
            if (mem1_axi_arvalid && mem1_axi_arready) begin
                mem1_ar_arb_locked <= 1'b0;
                mem1_ar_arb_rr <= (mem1_ar_arb_gnt == 2'd2) ? 2'd0 : mem1_ar_arb_gnt + 1'b1;
            end else if (mem1_axi_arvalid) begin
                mem1_ar_arb_lock   <= mem1_ar_arb_gnt;
                mem1_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire dma_128b_ar_gnt_mem1 = mem1_ar_arb_gnt_valid && (mem1_ar_arb_gnt == 2'd0) && mem1_ar_arb_req[0];
    wire acc_128b_ar_gnt_mem1 = mem1_ar_arb_gnt_valid && (mem1_ar_arb_gnt == 2'd1) && mem1_ar_arb_req[1];
    wire io_128b_ar_gnt_mem1 = mem1_ar_arb_gnt_valid && (mem1_ar_arb_gnt == 2'd2) && mem1_ar_arb_req[2];
    assign dma_128b_ar_slot_mem1_ready = dma_128b_ar_gnt_mem1 && mem1_axi_arready;
    assign acc_128b_ar_slot_mem1_ready = acc_128b_ar_gnt_mem1 && mem1_axi_arready;
    assign io_128b_ar_slot_mem1_ready = io_128b_ar_gnt_mem1 && mem1_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign mem1_axi_arid = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.id : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.id : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.id : '0);
    assign mem1_axi_araddr = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.addr : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.addr : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.addr : '0);
    assign mem1_axi_arlen = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.len : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.len : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.len : '0);
    assign mem1_axi_arsize = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.size : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.size : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.size : '0);
    assign mem1_axi_arburst = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.burst : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.burst : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.burst : '0);
    assign mem1_axi_arlock = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.lock : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.lock : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.lock : '0);
    assign mem1_axi_arcache = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.cache : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.cache : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.cache : '0);
    assign mem1_axi_arprot = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.prot : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.prot : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.prot : '0);
    assign mem1_axi_arqos = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.qos : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.qos : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.qos : '0);
    assign mem1_axi_arregion = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.region : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.region : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.region : '0);
    assign mem1_axi_aruser = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.user : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.user : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.user : '0);
    assign mem1_axi_arnsaid = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.nsaid : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.nsaid : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.nsaid : '0);
    assign mem1_axi_artrace = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.trace : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.trace : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.trace : '0);
    assign mem1_axi_armpam = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.mpam : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.mpam : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.mpam : '0);
    assign mem1_axi_armecid = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.mecid : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.mecid : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.mecid : '0);
    assign mem1_axi_aridunq = (dma_128b_ar_gnt_mem1 ? dma_128b_ar_slot_mem1.idunq : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_128b_ar_slot_mem1.idunq : '0) |
        (io_128b_ar_gnt_mem1 ? io_128b_ar_slot_mem1.idunq : '0);
    assign mem1_axi_arvalid = dma_128b_ar_gnt_mem1 || acc_128b_ar_gnt_mem1 || io_128b_ar_gnt_mem1;

    // Rready (slave -> the master whose response arbiter granted it)
    assign mem1_axi_rready = (dma_128b_r_rgnt_mem1 ? dma_128b_rready : '0) |
        (acc_128b_r_rgnt_mem1 ? acc_128b_rready : '0) |
        (io_128b_r_rgnt_mem1 ? io_128b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign mem1_axi_bridge_id_ar = (dma_128b_ar_gnt_mem1 ? dma_bridge_id_ar : '0) |
        (acc_128b_ar_gnt_mem1 ? acc_bridge_id_ar : '0) |
        (io_128b_ar_gnt_mem1 ? io_bridge_id_ar : '0);


    // ================================================================
    // Slave 2: mem2 (64b)
    // ================================================================
    // Single master: cpu → mem2
    // Master width: 64b, Slave width: 64b
    // Using 64b path from adapter

    // AW channel (gated by address re-decode -- see _addr_decode_expr)
    wire cpu_64b_aw_to_mem2 = ((cpu_64b_aw.addr >= 32'h30000000) && (cpu_64b_aw.addr <= 32'h3fffffff));
    wire cpu_64b_aw_gnt_mem2 = cpu_64b_aw_to_mem2 && !cpu_64b_aw_hold_mem2;
    assign mem2_axi_awid     = cpu_64b_aw_to_mem2 ? cpu_64b_aw.id : '0;
    assign mem2_axi_awaddr   = cpu_64b_aw_to_mem2 ? cpu_64b_aw.addr : '0;
    assign mem2_axi_awlen    = cpu_64b_aw_to_mem2 ? cpu_64b_aw.len : '0;
    assign mem2_axi_awsize   = cpu_64b_aw_to_mem2 ? cpu_64b_aw.size : '0;
    assign mem2_axi_awburst  = cpu_64b_aw_to_mem2 ? cpu_64b_aw.burst : '0;
    assign mem2_axi_awlock   = cpu_64b_aw_to_mem2 ? cpu_64b_aw.lock : '0;
    assign mem2_axi_awcache  = cpu_64b_aw_to_mem2 ? cpu_64b_aw.cache : '0;
    assign mem2_axi_awprot   = cpu_64b_aw_to_mem2 ? cpu_64b_aw.prot : '0;
    assign mem2_axi_awqos    = cpu_64b_aw_to_mem2 ? cpu_64b_aw.qos : '0;
    assign mem2_axi_awregion = cpu_64b_aw_to_mem2 ? cpu_64b_aw.region : '0;
    assign mem2_axi_awuser   = cpu_64b_aw_to_mem2 ? cpu_64b_aw.user : '0;
    assign mem2_axi_awnsaid  = cpu_64b_aw_to_mem2 ? cpu_64b_aw.nsaid : '0;  // AXI5 sideband
    assign mem2_axi_awtrace  = cpu_64b_aw_to_mem2 ? cpu_64b_aw.trace : '0;  // AXI5 sideband
    assign mem2_axi_awmpam  = cpu_64b_aw_to_mem2 ? cpu_64b_aw.mpam : '0;  // AXI5 sideband
    assign mem2_axi_awmecid  = cpu_64b_aw_to_mem2 ? cpu_64b_aw.mecid : '0;  // AXI5 sideband
    assign mem2_axi_awidunq  = cpu_64b_aw_to_mem2 ? cpu_64b_aw.idunq : '0;  // AXI5 sideband
    assign mem2_axi_awatop  = cpu_64b_aw_to_mem2 ? cpu_64b_aw.atop : '0;  // AXI5 sideband
    assign mem2_axi_awvalid  = cpu_64b_aw_gnt_mem2 && cpu_64b_awvalid;

    assign cpu_64b_w_sel_mem2 = cpu_64b_w_to_mem2;

    // W channel (gated by the W destination FIFO head)
    assign mem2_axi_wdata  = cpu_64b_w_to_mem2 ? cpu_64b_w.data : '0;
    assign mem2_axi_wstrb  = cpu_64b_w_to_mem2 ? cpu_64b_w.strb : '0;
    assign mem2_axi_wlast  = cpu_64b_w_to_mem2 ? cpu_64b_w.last : '0;
    assign mem2_axi_wuser  = cpu_64b_w_to_mem2 ? cpu_64b_w.user : '0;
    assign mem2_axi_wpoison = cpu_64b_w_to_mem2 ? cpu_64b_w.poison : '0;  // AXI5 sideband
    assign mem2_axi_wvalid = cpu_64b_w_to_mem2 && cpu_64b_wvalid;

    // Bready (master → slave) — gated on bid_valid so the path stays
    // open through the entire B handshake, not just the AW phase.
    assign mem2_axi_bready = cpu_64b_b_rgnt_mem2 ? cpu_64b_bready : '0;

    // Bridge ID (master → slave)
    assign mem2_axi_bridge_id_aw = cpu_64b_aw_to_mem2 ? cpu_bridge_id_aw : '0;

    // AR channel (gated by address re-decode -- see _addr_decode_expr)
    wire cpu_64b_ar_to_mem2 = ((cpu_64b_ar.addr >= 32'h30000000) && (cpu_64b_ar.addr <= 32'h3fffffff));
    wire cpu_64b_ar_gnt_mem2 = cpu_64b_ar_to_mem2;
    assign mem2_axi_arid     = cpu_64b_ar_to_mem2 ? cpu_64b_ar.id : '0;
    assign mem2_axi_araddr   = cpu_64b_ar_to_mem2 ? cpu_64b_ar.addr : '0;
    assign mem2_axi_arlen    = cpu_64b_ar_to_mem2 ? cpu_64b_ar.len : '0;
    assign mem2_axi_arsize   = cpu_64b_ar_to_mem2 ? cpu_64b_ar.size : '0;
    assign mem2_axi_arburst  = cpu_64b_ar_to_mem2 ? cpu_64b_ar.burst : '0;
    assign mem2_axi_arlock   = cpu_64b_ar_to_mem2 ? cpu_64b_ar.lock : '0;
    assign mem2_axi_arcache  = cpu_64b_ar_to_mem2 ? cpu_64b_ar.cache : '0;
    assign mem2_axi_arprot   = cpu_64b_ar_to_mem2 ? cpu_64b_ar.prot : '0;
    assign mem2_axi_arqos    = cpu_64b_ar_to_mem2 ? cpu_64b_ar.qos : '0;
    assign mem2_axi_arregion = cpu_64b_ar_to_mem2 ? cpu_64b_ar.region : '0;
    assign mem2_axi_aruser   = cpu_64b_ar_to_mem2 ? cpu_64b_ar.user : '0;
    assign mem2_axi_arnsaid  = cpu_64b_ar_to_mem2 ? cpu_64b_ar.nsaid : '0;  // AXI5 sideband
    assign mem2_axi_artrace  = cpu_64b_ar_to_mem2 ? cpu_64b_ar.trace : '0;  // AXI5 sideband
    assign mem2_axi_armpam  = cpu_64b_ar_to_mem2 ? cpu_64b_ar.mpam : '0;  // AXI5 sideband
    assign mem2_axi_armecid  = cpu_64b_ar_to_mem2 ? cpu_64b_ar.mecid : '0;  // AXI5 sideband
    assign mem2_axi_aridunq  = cpu_64b_ar_to_mem2 ? cpu_64b_ar.idunq : '0;  // AXI5 sideband
    assign mem2_axi_arvalid  = cpu_64b_ar_to_mem2 && cpu_64b_arvalid;

    // Rready (master → slave) — gated on rid_valid so the path stays
    // open through the entire R handshake, not just the AR phase.
    assign mem2_axi_rready = cpu_64b_r_rgnt_mem2 ? cpu_64b_rready : '0;

    // Bridge ID (master → slave)
    assign mem2_axi_bridge_id_ar = cpu_64b_ar_to_mem2 ? cpu_bridge_id_ar : '0;


    // ================================================================
    // Slave 3: mem3 (64b)
    // ================================================================
    // mem3: 3 masters on per-master lanes, arbitrated on mem3's own clock in its slave adapter (bridge W9)
    wire dma_64b_aw_to_mem3 = ((dma_64b_aw.addr >= 32'h40000000) && (dma_64b_aw.addr <= 32'h4fffffff));
    wire dma_64b_ar_to_mem3 = ((dma_64b_ar.addr >= 32'h40000000) && (dma_64b_ar.addr <= 32'h4fffffff));
    wire acc_64b_aw_to_mem3 = ((acc_64b_aw.addr >= 32'h40000000) && (acc_64b_aw.addr <= 32'h4fffffff));
    wire acc_64b_ar_to_mem3 = ((acc_64b_ar.addr >= 32'h40000000) && (acc_64b_ar.addr <= 32'h4fffffff));
    wire io_64b_aw_to_mem3 = ((io_64b_aw.addr >= 32'h40000000) && (io_64b_aw.addr <= 32'h4fffffff));
    wire io_64b_ar_to_mem3 = ((io_64b_ar.addr >= 32'h40000000) && (io_64b_ar.addr <= 32'h4fffffff));
    assign mem3_axi_lane_awvalid[0] = dma_64b_aw_to_mem3 && !dma_64b_aw_hold_mem3 && dma_64b_awvalid;
    assign mem3_axi_lane_aw[0*68 +: 68] = {dma_64b_aw.id, dma_64b_aw.addr, dma_64b_aw.len, dma_64b_aw.size, dma_64b_aw.burst, dma_64b_aw.lock, dma_64b_aw.cache, dma_64b_aw.prot, dma_64b_aw.qos, dma_64b_aw.region, dma_64b_aw.user};
    assign dma_64b_w_sel_mem3 = dma_64b_w_to_mem3;
    assign mem3_axi_lane_wvalid[0] = dma_64b_w_to_mem3 && dma_64b_wvalid;
    assign mem3_axi_lane_w[0*74 +: 74] = {dma_64b_w.data, dma_64b_w.strb, dma_64b_w.last, dma_64b_w.user};
    assign mem3_axi_lane_arvalid[0] = dma_64b_ar_to_mem3 && dma_64b_arvalid;
    assign mem3_axi_lane_ar[0*68 +: 68] = {dma_64b_ar.id, dma_64b_ar.addr, dma_64b_ar.len, dma_64b_ar.size, dma_64b_ar.burst, dma_64b_ar.lock, dma_64b_ar.cache, dma_64b_ar.prot, dma_64b_ar.qos, dma_64b_ar.region, dma_64b_ar.user};
    assign mem3_axi_lane_awvalid[1] = acc_64b_aw_to_mem3 && !acc_64b_aw_hold_mem3 && acc_64b_awvalid;
    assign mem3_axi_lane_aw[1*68 +: 68] = {acc_64b_aw.id, acc_64b_aw.addr, acc_64b_aw.len, acc_64b_aw.size, acc_64b_aw.burst, acc_64b_aw.lock, acc_64b_aw.cache, acc_64b_aw.prot, acc_64b_aw.qos, acc_64b_aw.region, acc_64b_aw.user};
    assign acc_64b_w_sel_mem3 = acc_64b_w_to_mem3;
    assign mem3_axi_lane_wvalid[1] = acc_64b_w_to_mem3 && acc_64b_wvalid;
    assign mem3_axi_lane_w[1*74 +: 74] = {acc_64b_w.data, acc_64b_w.strb, acc_64b_w.last, acc_64b_w.user};
    assign mem3_axi_lane_arvalid[1] = acc_64b_ar_to_mem3 && acc_64b_arvalid;
    assign mem3_axi_lane_ar[1*68 +: 68] = {acc_64b_ar.id, acc_64b_ar.addr, acc_64b_ar.len, acc_64b_ar.size, acc_64b_ar.burst, acc_64b_ar.lock, acc_64b_ar.cache, acc_64b_ar.prot, acc_64b_ar.qos, acc_64b_ar.region, acc_64b_ar.user};
    assign mem3_axi_lane_awvalid[2] = io_64b_aw_to_mem3 && !io_64b_aw_hold_mem3 && io_64b_awvalid;
    assign mem3_axi_lane_aw[2*68 +: 68] = {io_64b_aw.id, io_64b_aw.addr, io_64b_aw.len, io_64b_aw.size, io_64b_aw.burst, io_64b_aw.lock, io_64b_aw.cache, io_64b_aw.prot, io_64b_aw.qos, io_64b_aw.region, io_64b_aw.user};
    assign io_64b_w_sel_mem3 = io_64b_w_to_mem3;
    assign mem3_axi_lane_wvalid[2] = io_64b_w_to_mem3 && io_64b_wvalid;
    assign mem3_axi_lane_w[2*74 +: 74] = {io_64b_w.data, io_64b_w.strb, io_64b_w.last, io_64b_w.user};
    assign mem3_axi_lane_arvalid[2] = io_64b_ar_to_mem3 && io_64b_arvalid;
    assign mem3_axi_lane_ar[2*68 +: 68] = {io_64b_ar.id, io_64b_ar.addr, io_64b_ar.len, io_64b_ar.size, io_64b_ar.burst, io_64b_ar.lock, io_64b_ar.cache, io_64b_ar.prot, io_64b_ar.qos, io_64b_ar.region, io_64b_ar.user};
    assign mem3_axi_awid = '0;
    assign mem3_axi_awaddr = '0;
    assign mem3_axi_awlen = '0;
    assign mem3_axi_awsize = '0;
    assign mem3_axi_awburst = '0;
    assign mem3_axi_awlock = '0;
    assign mem3_axi_awcache = '0;
    assign mem3_axi_awprot = '0;
    assign mem3_axi_awqos = '0;
    assign mem3_axi_awregion = '0;
    assign mem3_axi_awuser = '0;
    assign mem3_axi_awvalid = '0;
    assign mem3_axi_wdata = '0;
    assign mem3_axi_wstrb = '0;
    assign mem3_axi_wlast = '0;
    assign mem3_axi_wuser = '0;
    assign mem3_axi_wvalid = '0;
    assign mem3_axi_bridge_id_aw = '0;
    assign mem3_axi_arid = '0;
    assign mem3_axi_araddr = '0;
    assign mem3_axi_arlen = '0;
    assign mem3_axi_arsize = '0;
    assign mem3_axi_arburst = '0;
    assign mem3_axi_arlock = '0;
    assign mem3_axi_arcache = '0;
    assign mem3_axi_arprot = '0;
    assign mem3_axi_arqos = '0;
    assign mem3_axi_arregion = '0;
    assign mem3_axi_aruser = '0;
    assign mem3_axi_arvalid = '0;
    assign mem3_axi_bridge_id_ar = '0;
    assign mem3_axi_bready = (dma_64b_b_rgnt_mem3 ? dma_64b_bready : '0) |
        (acc_64b_b_rgnt_mem3 ? acc_64b_bready : '0) |
        (io_64b_b_rgnt_mem3 ? io_64b_bready : '0);
    assign mem3_axi_rready = (dma_64b_r_rgnt_mem3 ? dma_64b_rready : '0) |
        (acc_64b_r_rgnt_mem3 ? acc_64b_rready : '0) |
        (io_64b_r_rgnt_mem3 ? io_64b_rready : '0);


    // ================================================================
    // Slave 4: subtractive (128b)
    // ================================================================
    // Multi-master (4 masters) → subtractive
    //   - cpu (rw)
    //   - dma (rw)
    //   - acc (rw)
    //   - io (rw)

    wire cpu_128b_aw_to_subtractive = !(((cpu_128b_aw.addr <= 32'h0fffffff)) || (((cpu_128b_aw.addr >= 32'h30000000) && (cpu_128b_aw.addr <= 32'h3fffffff))));
    wire cpu_128b_ar_to_subtractive = !(((cpu_128b_ar.addr <= 32'h0fffffff)) || (((cpu_128b_ar.addr >= 32'h30000000) && (cpu_128b_ar.addr <= 32'h3fffffff))));
    wire dma_128b_aw_to_subtractive = !((((dma_128b_aw.addr >= 32'h10000000) && (dma_128b_aw.addr <= 32'h1fffffff))) || (((dma_128b_aw.addr >= 32'h40000000) && (dma_128b_aw.addr <= 32'h4fffffff))));
    wire dma_128b_ar_to_subtractive = !((((dma_128b_ar.addr >= 32'h10000000) && (dma_128b_ar.addr <= 32'h1fffffff))) || (((dma_128b_ar.addr >= 32'h40000000) && (dma_128b_ar.addr <= 32'h4fffffff))));
    wire acc_128b_aw_to_subtractive = !((((acc_128b_aw.addr >= 32'h10000000) && (acc_128b_aw.addr <= 32'h1fffffff))) || (((acc_128b_aw.addr >= 32'h40000000) && (acc_128b_aw.addr <= 32'h4fffffff))));
    wire acc_128b_ar_to_subtractive = !((((acc_128b_ar.addr >= 32'h10000000) && (acc_128b_ar.addr <= 32'h1fffffff))) || (((acc_128b_ar.addr >= 32'h40000000) && (acc_128b_ar.addr <= 32'h4fffffff))));
    wire io_128b_aw_to_subtractive = !((((io_128b_aw.addr >= 32'h10000000) && (io_128b_aw.addr <= 32'h1fffffff))) || (((io_128b_aw.addr >= 32'h40000000) && (io_128b_aw.addr <= 32'h4fffffff))));
    wire io_128b_ar_to_subtractive = !((((io_128b_ar.addr >= 32'h10000000) && (io_128b_ar.addr <= 32'h1fffffff))) || (((io_128b_ar.addr >= 32'h40000000) && (io_128b_ar.addr <= 32'h4fffffff))));

    // AW request slots for subtractive: arbitration at the slave pins
    assign cpu_128b_aw_slot_subtractive_in_valid = cpu_128b_aw_to_subtractive && cpu_128b_awvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_128b_aw_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_128b_aw_slot_subtractive_in_valid), .wr_ready(cpu_128b_aw_slot_subtractive_in_ready), .wr_data(cpu_128b_aw),
        .rd_valid(cpu_128b_aw_slot_subtractive_valid), .rd_ready(cpu_128b_aw_slot_subtractive_ready), .rd_data(cpu_128b_aw_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_128b_aw_slot_subtractive_in_valid = dma_128b_aw_to_subtractive && dma_128b_awvalid && !dma_128b_aw_hold_subtractive;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_dma_128b_aw_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_128b_aw_slot_subtractive_in_valid), .wr_ready(dma_128b_aw_slot_subtractive_in_ready), .wr_data(dma_128b_aw),
        .rd_valid(dma_128b_aw_slot_subtractive_valid), .rd_ready(dma_128b_aw_slot_subtractive_ready), .rd_data(dma_128b_aw_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_128b_aw_slot_subtractive_in_valid = acc_128b_aw_to_subtractive && acc_128b_awvalid && !acc_128b_aw_hold_subtractive;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_acc_128b_aw_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_128b_aw_slot_subtractive_in_valid), .wr_ready(acc_128b_aw_slot_subtractive_in_ready), .wr_data(acc_128b_aw),
        .rd_valid(acc_128b_aw_slot_subtractive_valid), .rd_ready(acc_128b_aw_slot_subtractive_ready), .rd_data(acc_128b_aw_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_128b_aw_slot_subtractive_in_valid = io_128b_aw_to_subtractive && io_128b_awvalid && !io_128b_aw_hold_subtractive;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_io_128b_aw_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_128b_aw_slot_subtractive_in_valid), .wr_ready(io_128b_aw_slot_subtractive_in_ready), .wr_data(io_128b_aw),
        .rd_valid(io_128b_aw_slot_subtractive_valid), .rd_ready(io_128b_aw_slot_subtractive_ready), .rd_data(io_128b_aw_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for subtractive: round-robin, lock until handshake ----
    logic [3:0] subtractive_aw_arb_req;
    assign subtractive_aw_arb_req = {io_128b_aw_slot_subtractive_valid, acc_128b_aw_slot_subtractive_valid, dma_128b_aw_slot_subtractive_valid, cpu_128b_aw_slot_subtractive_valid};
    logic [1:0] subtractive_aw_arb_lock, subtractive_aw_arb_rr;
    logic subtractive_aw_arb_locked;
    wire [1:0] subtractive_aw_arb_pick = (subtractive_aw_arb_rr == 2'd0) ? (subtractive_aw_arb_req[0] ? 2'd0 : subtractive_aw_arb_req[1] ? 2'd1 : subtractive_aw_arb_req[2] ? 2'd2 : 2'd3) : 
        (subtractive_aw_arb_rr == 2'd1) ? (subtractive_aw_arb_req[1] ? 2'd1 : subtractive_aw_arb_req[2] ? 2'd2 : subtractive_aw_arb_req[3] ? 2'd3 : 2'd0) : 
        (subtractive_aw_arb_rr == 2'd2) ? (subtractive_aw_arb_req[2] ? 2'd2 : subtractive_aw_arb_req[3] ? 2'd3 : subtractive_aw_arb_req[0] ? 2'd0 : 2'd1) : 
        subtractive_aw_arb_req[3] ? 2'd3 : subtractive_aw_arb_req[0] ? 2'd0 : subtractive_aw_arb_req[1] ? 2'd1 : 2'd2;
    wire subtractive_aw_arb_gnt_valid = subtractive_aw_arb_locked || (|subtractive_aw_arb_req);
    wire [1:0] subtractive_aw_arb_gnt = subtractive_aw_arb_locked ? subtractive_aw_arb_lock : subtractive_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_aw_arb_lock   <= '0;
            subtractive_aw_arb_rr     <= '0;
            subtractive_aw_arb_locked <= 1'b0;
        end else begin
            if (subtractive_axi_awvalid && subtractive_axi_awready) begin
                subtractive_aw_arb_locked <= 1'b0;
                subtractive_aw_arb_rr <= (subtractive_aw_arb_gnt == 2'd3) ? 2'd0 : subtractive_aw_arb_gnt + 1'b1;
            end else if (subtractive_axi_awvalid) begin
                subtractive_aw_arb_lock   <= subtractive_aw_arb_gnt;
                subtractive_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 2'd0) && subtractive_aw_arb_req[0];
    wire dma_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 2'd1) && subtractive_aw_arb_req[1];
    wire acc_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 2'd2) && subtractive_aw_arb_req[2];
    wire io_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 2'd3) && subtractive_aw_arb_req[3];
    assign cpu_128b_aw_slot_subtractive_ready = cpu_128b_aw_gnt_subtractive && subtractive_axi_awready;
    assign dma_128b_aw_slot_subtractive_ready = dma_128b_aw_gnt_subtractive && subtractive_axi_awready;
    assign acc_128b_aw_slot_subtractive_ready = acc_128b_aw_gnt_subtractive && subtractive_axi_awready;
    assign io_128b_aw_slot_subtractive_ready = io_128b_aw_gnt_subtractive && subtractive_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign subtractive_axi_awid = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.id : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.id : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.id : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.id : '0);
    assign subtractive_axi_awaddr = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.addr : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.addr : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.addr : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.addr : '0);
    assign subtractive_axi_awlen = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.len : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.len : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.len : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.len : '0);
    assign subtractive_axi_awsize = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.size : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.size : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.size : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.size : '0);
    assign subtractive_axi_awburst = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.burst : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.burst : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.burst : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.burst : '0);
    assign subtractive_axi_awlock = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.lock : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.lock : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.lock : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.lock : '0);
    assign subtractive_axi_awcache = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.cache : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.cache : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.cache : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.cache : '0);
    assign subtractive_axi_awprot = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.prot : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.prot : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.prot : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.prot : '0);
    assign subtractive_axi_awqos = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.qos : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.qos : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.qos : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.qos : '0);
    assign subtractive_axi_awregion = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.region : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.region : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.region : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.region : '0);
    assign subtractive_axi_awuser = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.user : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.user : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.user : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.user : '0);
    assign subtractive_axi_awvalid = cpu_128b_aw_gnt_subtractive || dma_128b_aw_gnt_subtractive || acc_128b_aw_gnt_subtractive || io_128b_aw_gnt_subtractive;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [1:0] subtractive_wowner_mem [16];
    logic [4:0] subtractive_wowner_wptr, subtractive_wowner_rptr;
    logic subtractive_wowner_ahead;
    wire subtractive_wowner_valid = (subtractive_wowner_wptr != subtractive_wowner_rptr);
    wire subtractive_wowner_byp = !subtractive_wowner_valid && !subtractive_wowner_ahead && subtractive_axi_awvalid;
    wire subtractive_wowner_aw_hs = subtractive_axi_awvalid && subtractive_axi_awready;
    wire subtractive_wowner_w_end = subtractive_axi_wvalid && subtractive_axi_wready && subtractive_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_wowner_wptr  <= '0;
            subtractive_wowner_rptr  <= '0;
            subtractive_wowner_ahead <= 1'b0;
        end else begin
            if (subtractive_wowner_aw_hs && subtractive_wowner_ahead) begin
                subtractive_wowner_ahead <= 1'b0;   // its W already went
            end else if (subtractive_wowner_aw_hs && !(subtractive_wowner_byp && subtractive_wowner_w_end)) begin
                subtractive_wowner_mem[subtractive_wowner_wptr[3:0]] <= subtractive_aw_arb_gnt;
                subtractive_wowner_wptr <= subtractive_wowner_wptr + 1'b1;
            end else if (!subtractive_wowner_aw_hs && subtractive_wowner_byp && subtractive_wowner_w_end) begin
                subtractive_wowner_ahead <= 1'b1;
            end
            if (subtractive_wowner_valid && subtractive_wowner_w_end) begin
                subtractive_wowner_rptr <= subtractive_wowner_rptr + 1'b1;
            end
        end
    )
    wire [1:0] subtractive_wowner_head = subtractive_wowner_valid ? subtractive_wowner_mem[subtractive_wowner_rptr[3:0]]
                                       : subtractive_aw_arb_gnt;
    assign cpu_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 2'd0) && cpu_128b_w_to_subtractive;
    assign dma_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 2'd1) && dma_128b_w_to_subtractive;
    assign acc_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 2'd2) && acc_128b_w_to_subtractive;
    assign io_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 2'd3) && io_128b_w_to_subtractive;

    // W channel (owner-gated mux across writing masters)
    assign subtractive_axi_wdata = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.data : '0) |
        ((dma_128b_w_sel_subtractive && dma_128b_wvalid) ? dma_128b_w.data : '0) |
        ((acc_128b_w_sel_subtractive && acc_128b_wvalid) ? acc_128b_w.data : '0) |
        ((io_128b_w_sel_subtractive && io_128b_wvalid) ? io_128b_w.data : '0);
    assign subtractive_axi_wstrb = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.strb : '0) |
        ((dma_128b_w_sel_subtractive && dma_128b_wvalid) ? dma_128b_w.strb : '0) |
        ((acc_128b_w_sel_subtractive && acc_128b_wvalid) ? acc_128b_w.strb : '0) |
        ((io_128b_w_sel_subtractive && io_128b_wvalid) ? io_128b_w.strb : '0);
    assign subtractive_axi_wlast = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.last : '0) |
        ((dma_128b_w_sel_subtractive && dma_128b_wvalid) ? dma_128b_w.last : '0) |
        ((acc_128b_w_sel_subtractive && acc_128b_wvalid) ? acc_128b_w.last : '0) |
        ((io_128b_w_sel_subtractive && io_128b_wvalid) ? io_128b_w.last : '0);
    assign subtractive_axi_wuser = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.user : '0) |
        ((dma_128b_w_sel_subtractive && dma_128b_wvalid) ? dma_128b_w.user : '0) |
        ((acc_128b_w_sel_subtractive && acc_128b_wvalid) ? acc_128b_w.user : '0) |
        ((io_128b_w_sel_subtractive && io_128b_wvalid) ? io_128b_w.user : '0);
    assign subtractive_axi_wvalid = (cpu_128b_w_sel_subtractive && cpu_128b_wvalid) || (dma_128b_w_sel_subtractive && dma_128b_wvalid) || (acc_128b_w_sel_subtractive && acc_128b_wvalid) || (io_128b_w_sel_subtractive && io_128b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign subtractive_axi_bready = (cpu_128b_b_rgnt_subtractive ? cpu_128b_bready : '0) |
        (dma_128b_b_rgnt_subtractive ? dma_128b_bready : '0) |
        (acc_128b_b_rgnt_subtractive ? acc_128b_bready : '0) |
        (io_128b_b_rgnt_subtractive ? io_128b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign subtractive_axi_bridge_id_aw = (cpu_128b_aw_gnt_subtractive ? cpu_bridge_id_aw : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_bridge_id_aw : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_bridge_id_aw : '0) |
        (io_128b_aw_gnt_subtractive ? io_bridge_id_aw : '0);

    // AR request slots for subtractive: arbitration at the slave pins
    assign cpu_128b_ar_slot_subtractive_in_valid = cpu_128b_ar_to_subtractive && cpu_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_128b_ar_slot_subtractive_in_valid), .wr_ready(cpu_128b_ar_slot_subtractive_in_ready), .wr_data(cpu_128b_ar),
        .rd_valid(cpu_128b_ar_slot_subtractive_valid), .rd_ready(cpu_128b_ar_slot_subtractive_ready), .rd_data(cpu_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_128b_ar_slot_subtractive_in_valid = dma_128b_ar_to_subtractive && dma_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_dma_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_128b_ar_slot_subtractive_in_valid), .wr_ready(dma_128b_ar_slot_subtractive_in_ready), .wr_data(dma_128b_ar),
        .rd_valid(dma_128b_ar_slot_subtractive_valid), .rd_ready(dma_128b_ar_slot_subtractive_ready), .rd_data(dma_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_128b_ar_slot_subtractive_in_valid = acc_128b_ar_to_subtractive && acc_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_acc_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_128b_ar_slot_subtractive_in_valid), .wr_ready(acc_128b_ar_slot_subtractive_in_ready), .wr_data(acc_128b_ar),
        .rd_valid(acc_128b_ar_slot_subtractive_valid), .rd_ready(acc_128b_ar_slot_subtractive_ready), .rd_data(acc_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_128b_ar_slot_subtractive_in_valid = io_128b_ar_to_subtractive && io_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_io_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_128b_ar_slot_subtractive_in_valid), .wr_ready(io_128b_ar_slot_subtractive_in_ready), .wr_data(io_128b_ar),
        .rd_valid(io_128b_ar_slot_subtractive_valid), .rd_ready(io_128b_ar_slot_subtractive_ready), .rd_data(io_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for subtractive: round-robin, lock until handshake ----
    logic [3:0] subtractive_ar_arb_req;
    assign subtractive_ar_arb_req = {io_128b_ar_slot_subtractive_valid, acc_128b_ar_slot_subtractive_valid, dma_128b_ar_slot_subtractive_valid, cpu_128b_ar_slot_subtractive_valid};
    logic [1:0] subtractive_ar_arb_lock, subtractive_ar_arb_rr;
    logic subtractive_ar_arb_locked;
    wire [1:0] subtractive_ar_arb_pick = (subtractive_ar_arb_rr == 2'd0) ? (subtractive_ar_arb_req[0] ? 2'd0 : subtractive_ar_arb_req[1] ? 2'd1 : subtractive_ar_arb_req[2] ? 2'd2 : 2'd3) : 
        (subtractive_ar_arb_rr == 2'd1) ? (subtractive_ar_arb_req[1] ? 2'd1 : subtractive_ar_arb_req[2] ? 2'd2 : subtractive_ar_arb_req[3] ? 2'd3 : 2'd0) : 
        (subtractive_ar_arb_rr == 2'd2) ? (subtractive_ar_arb_req[2] ? 2'd2 : subtractive_ar_arb_req[3] ? 2'd3 : subtractive_ar_arb_req[0] ? 2'd0 : 2'd1) : 
        subtractive_ar_arb_req[3] ? 2'd3 : subtractive_ar_arb_req[0] ? 2'd0 : subtractive_ar_arb_req[1] ? 2'd1 : 2'd2;
    wire subtractive_ar_arb_gnt_valid = subtractive_ar_arb_locked || (|subtractive_ar_arb_req);
    wire [1:0] subtractive_ar_arb_gnt = subtractive_ar_arb_locked ? subtractive_ar_arb_lock : subtractive_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_ar_arb_lock   <= '0;
            subtractive_ar_arb_rr     <= '0;
            subtractive_ar_arb_locked <= 1'b0;
        end else begin
            if (subtractive_axi_arvalid && subtractive_axi_arready) begin
                subtractive_ar_arb_locked <= 1'b0;
                subtractive_ar_arb_rr <= (subtractive_ar_arb_gnt == 2'd3) ? 2'd0 : subtractive_ar_arb_gnt + 1'b1;
            end else if (subtractive_axi_arvalid) begin
                subtractive_ar_arb_lock   <= subtractive_ar_arb_gnt;
                subtractive_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 2'd0) && subtractive_ar_arb_req[0];
    wire dma_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 2'd1) && subtractive_ar_arb_req[1];
    wire acc_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 2'd2) && subtractive_ar_arb_req[2];
    wire io_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 2'd3) && subtractive_ar_arb_req[3];
    assign cpu_128b_ar_slot_subtractive_ready = cpu_128b_ar_gnt_subtractive && subtractive_axi_arready;
    assign dma_128b_ar_slot_subtractive_ready = dma_128b_ar_gnt_subtractive && subtractive_axi_arready;
    assign acc_128b_ar_slot_subtractive_ready = acc_128b_ar_gnt_subtractive && subtractive_axi_arready;
    assign io_128b_ar_slot_subtractive_ready = io_128b_ar_gnt_subtractive && subtractive_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign subtractive_axi_arid = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.id : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.id : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.id : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.id : '0);
    assign subtractive_axi_araddr = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.addr : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.addr : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.addr : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.addr : '0);
    assign subtractive_axi_arlen = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.len : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.len : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.len : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.len : '0);
    assign subtractive_axi_arsize = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.size : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.size : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.size : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.size : '0);
    assign subtractive_axi_arburst = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.burst : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.burst : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.burst : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.burst : '0);
    assign subtractive_axi_arlock = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.lock : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.lock : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.lock : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.lock : '0);
    assign subtractive_axi_arcache = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.cache : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.cache : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.cache : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.cache : '0);
    assign subtractive_axi_arprot = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.prot : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.prot : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.prot : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.prot : '0);
    assign subtractive_axi_arqos = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.qos : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.qos : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.qos : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.qos : '0);
    assign subtractive_axi_arregion = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.region : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.region : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.region : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.region : '0);
    assign subtractive_axi_aruser = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.user : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.user : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.user : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.user : '0);
    assign subtractive_axi_arvalid = cpu_128b_ar_gnt_subtractive || dma_128b_ar_gnt_subtractive || acc_128b_ar_gnt_subtractive || io_128b_ar_gnt_subtractive;

    // Rready (slave -> the master whose response arbiter granted it)
    assign subtractive_axi_rready = (cpu_128b_r_rgnt_subtractive ? cpu_128b_rready : '0) |
        (dma_128b_r_rgnt_subtractive ? dma_128b_rready : '0) |
        (acc_128b_r_rgnt_subtractive ? acc_128b_rready : '0) |
        (io_128b_r_rgnt_subtractive ? io_128b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign subtractive_axi_bridge_id_ar = (cpu_128b_ar_gnt_subtractive ? cpu_bridge_id_ar : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_bridge_id_ar : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_bridge_id_ar : '0) |
        (io_128b_ar_gnt_subtractive ? io_bridge_id_ar : '0);


    // ================================================================
    // W destination FIFOs (per master width-path)
    // ================================================================
    // cpu 64b path -> mem0, mem2 (16 deep: max_outstanding)
    logic [0:0] cpu_64b_wdest_mem [16];
    logic [4:0] cpu_64b_wdest_wptr, cpu_64b_wdest_rptr;
    wire [0:0] cpu_64b_wdest_enc = cpu_64b_aw_to_mem2 ? 1'd1 : 1'd0;
    wire cpu_64b_wdest_push = cpu_64b_awvalid && cpu_64b_awready;
    wire cpu_64b_wdest_pop  = cpu_64b_wvalid && cpu_64b_wready && cpu_64b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_64b_wdest_wptr <= '0;
            cpu_64b_wdest_rptr <= '0;
        end else begin
            if (cpu_64b_wdest_push) begin
                cpu_64b_wdest_mem[cpu_64b_wdest_wptr[3:0]] <= cpu_64b_wdest_enc;
                cpu_64b_wdest_wptr <= cpu_64b_wdest_wptr + 1'b1;
            end
            if (cpu_64b_wdest_pop) begin
                cpu_64b_wdest_rptr <= cpu_64b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_64b_wdest_valid = (cpu_64b_wdest_wptr != cpu_64b_wdest_rptr);
    wire [0:0] cpu_64b_wdest_head = cpu_64b_wdest_mem[cpu_64b_wdest_rptr[3:0]];
    assign cpu_64b_w_to_mem0 = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 1'd0);
    assign cpu_64b_w_to_mem2 = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 1'd1);

    // cpu 128b path -> subtractive (16 deep: max_outstanding)
    logic [0:0] cpu_128b_wdest_mem [16];
    logic [4:0] cpu_128b_wdest_wptr, cpu_128b_wdest_rptr;
    wire [0:0] cpu_128b_wdest_enc = 1'd0;
    wire cpu_128b_wdest_push = cpu_128b_awvalid && cpu_128b_awready;
    wire cpu_128b_wdest_pop  = cpu_128b_wvalid && cpu_128b_wready && cpu_128b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_128b_wdest_wptr <= '0;
            cpu_128b_wdest_rptr <= '0;
        end else begin
            if (cpu_128b_wdest_push) begin
                cpu_128b_wdest_mem[cpu_128b_wdest_wptr[3:0]] <= cpu_128b_wdest_enc;
                cpu_128b_wdest_wptr <= cpu_128b_wdest_wptr + 1'b1;
            end
            if (cpu_128b_wdest_pop) begin
                cpu_128b_wdest_rptr <= cpu_128b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_128b_wdest_valid = (cpu_128b_wdest_wptr != cpu_128b_wdest_rptr);
    wire [0:0] cpu_128b_wdest_head = cpu_128b_wdest_mem[cpu_128b_wdest_rptr[3:0]];
    assign cpu_128b_w_to_subtractive = cpu_128b_wdest_valid && (cpu_128b_wdest_head == 1'd0);

    // dma 64b path -> mem3 (16 deep: max_outstanding)
    logic [0:0] dma_64b_wdest_mem [16];
    logic [4:0] dma_64b_wdest_wptr, dma_64b_wdest_rptr;
    wire [0:0] dma_64b_wdest_enc = 1'd0;
    wire dma_64b_wdest_push = dma_64b_awvalid && dma_64b_awready;
    wire dma_64b_wdest_pop  = dma_64b_wvalid && dma_64b_wready && dma_64b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            dma_64b_wdest_wptr <= '0;
            dma_64b_wdest_rptr <= '0;
        end else begin
            if (dma_64b_wdest_push) begin
                dma_64b_wdest_mem[dma_64b_wdest_wptr[3:0]] <= dma_64b_wdest_enc;
                dma_64b_wdest_wptr <= dma_64b_wdest_wptr + 1'b1;
            end
            if (dma_64b_wdest_pop) begin
                dma_64b_wdest_rptr <= dma_64b_wdest_rptr + 1'b1;
            end
        end
    )
    wire dma_64b_wdest_valid = (dma_64b_wdest_wptr != dma_64b_wdest_rptr);
    wire [0:0] dma_64b_wdest_head = dma_64b_wdest_mem[dma_64b_wdest_rptr[3:0]];
    assign dma_64b_w_to_mem3 = dma_64b_wdest_valid && (dma_64b_wdest_head == 1'd0);

    // dma 128b path -> mem1, subtractive (16 deep: max_outstanding)
    logic [0:0] dma_128b_wdest_mem [16];
    logic [4:0] dma_128b_wdest_wptr, dma_128b_wdest_rptr;
    wire [0:0] dma_128b_wdest_enc = dma_128b_aw_to_subtractive ? 1'd1 : 1'd0;
    wire dma_128b_wdest_push = dma_128b_awvalid && dma_128b_awready;
    wire dma_128b_wdest_pop  = dma_128b_wvalid && dma_128b_wready && dma_128b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            dma_128b_wdest_wptr <= '0;
            dma_128b_wdest_rptr <= '0;
        end else begin
            if (dma_128b_wdest_push) begin
                dma_128b_wdest_mem[dma_128b_wdest_wptr[3:0]] <= dma_128b_wdest_enc;
                dma_128b_wdest_wptr <= dma_128b_wdest_wptr + 1'b1;
            end
            if (dma_128b_wdest_pop) begin
                dma_128b_wdest_rptr <= dma_128b_wdest_rptr + 1'b1;
            end
        end
    )
    wire dma_128b_wdest_valid = (dma_128b_wdest_wptr != dma_128b_wdest_rptr);
    wire [0:0] dma_128b_wdest_head = dma_128b_wdest_mem[dma_128b_wdest_rptr[3:0]];
    assign dma_128b_w_to_mem1 = dma_128b_wdest_valid && (dma_128b_wdest_head == 1'd0);
    assign dma_128b_w_to_subtractive = dma_128b_wdest_valid && (dma_128b_wdest_head == 1'd1);

    // acc 64b path -> mem3 (16 deep: max_outstanding)
    logic [0:0] acc_64b_wdest_mem [16];
    logic [4:0] acc_64b_wdest_wptr, acc_64b_wdest_rptr;
    wire [0:0] acc_64b_wdest_enc = 1'd0;
    wire acc_64b_wdest_push = acc_64b_awvalid && acc_64b_awready;
    wire acc_64b_wdest_pop  = acc_64b_wvalid && acc_64b_wready && acc_64b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            acc_64b_wdest_wptr <= '0;
            acc_64b_wdest_rptr <= '0;
        end else begin
            if (acc_64b_wdest_push) begin
                acc_64b_wdest_mem[acc_64b_wdest_wptr[3:0]] <= acc_64b_wdest_enc;
                acc_64b_wdest_wptr <= acc_64b_wdest_wptr + 1'b1;
            end
            if (acc_64b_wdest_pop) begin
                acc_64b_wdest_rptr <= acc_64b_wdest_rptr + 1'b1;
            end
